# Get all PRs and commits from GameOfDominoes
prs_file = glob.glob('/home/agent/.gemini/tmp/workspace/tool-outputs/**/mcp_mcp72a4a9d8_github_list_pull_requests_*.txt', recursive=True)[0]
commits_file = glob.glob('/home/agent/.gemini/tmp/workspace/tool-outputs/**/mcp_mcp72a4a9d8_github_list_commits_*.txt', recursive=True)[0]

prs = json.load(open(prs_file))
commits = json.load(open(commits_file))

files = sorted(glob.glob('/home/agent/.gemini/tmp/workspace/tool-outputs/**/mcp_mcp72a4a9d8_linear_list_issues_*.txt', recursive=True))
all_issues = {}
for f in files:
    try:
        data = json.load(open(f))
        issues_list = data.get('issues', []) if isinstance(data, dict) else (json.loads(data['output']).get('issues', []) if 'output' in data else [])
        for issue in issues_list:
            if issue.get('team_id') == 'team_ART':
                all_issues[issue['id']] = issue
    except Exception as e:
        pass

closed_states = {'Done', 'Canceled', 'Duplicate'}
open_issues = [i for i in all_issues.values() if i.get('state_id') not in closed_states]

for issue in sorted(open_issues, key=lambda x: x['number']):
    key = issue['identifier']
    title = issue['title']
    state = issue['state_id']

    found = []

    # Check PRs
    for pr in prs:
        body = pr.get('body') or ''
        pr_title = pr.get('title') or ''
        head_ref = pr.get('head', {}).get('ref') or ''
        if key.lower() in body.lower() or key.lower() in pr_title.lower() or key.lower() in head_ref.lower():
            found.append(f\"GitHub PR #{pr['number']} ({pr['state']}): {pr['title']}\")

    # Check Commits
    for c in commits:
        msg = c.get('commit', {}).get('message') or ''
        if key.lower() in msg.lower():
            found.append(f\"Commit {c['sha'][:7]}: {msg.splitlines()[0]}\")

    print(f\"[{key}] ({state}) '{title}'\")
    if found:
        for f_item in found:
            print(f\"   -> {f_item}\")
    else:
        print(\"   -> (No direct GitHub commit/PR match found)\")
